export function changeThemeColor(color) {
  const rgbs = hexToRgb(color);
  const rgb = `${rgbs[0]},${rgbs[1]},${rgbs[2]}`;
  document.documentElement.style.setProperty("--primary-color", color);
  document.documentElement.style.setProperty("--primary-color-rgb", rgb);
  // 同步 Element Plus 内置主题变量（核心：--el-color-primary）
  document.documentElement.style.setProperty("--el-color-primary", color);

  // 计算并设置所有浅色变体...
  for (let i = 1; i <= 9; i++) {
    const whitePercentage = i * 10;
    const lightColor = mix("#ffffff", color, whitePercentage);
    document.documentElement.style.setProperty(`--primary-color-light-${i}`, lightColor);
    // Element Plus 对应浅色变量：--el-color-primary-light-1 ~ 9
    document.documentElement.style.setProperty(`--el-color-primary-light-${i}`, lightColor);
  }

  // 计算并设置所有深色变体...
  for (let i = 1; i <= 9; i++) {
    const blackPercentage = i * 10;
    const darkColor = mix(color, "#000000", 100 - blackPercentage);
    document.documentElement.style.setProperty(`--primary-color-dark-${i}`, darkColor);
    // Element Plus 对应深色变量：--el-color-primary-dark-1 ~ 9
    document.documentElement.style.setProperty(`--el-color-primary-dark-${i}`, darkColor);
  }

  // 下面 danger/success/warning 的逻辑保持不变...
}
