    _beginApiLoading() {
      if (this._apiLoadingDepth === 0) {
        uni.showLoading({
          title: '加载中',
          mask: true,
        })
      }
      this._apiLoadingDepth++
    },
    _endApiLoading() {
      this._apiLoadingDepth = Math.max(0, this._apiLoadingDepth - 1)
      if (this._apiLoadingDepth === 0) {
        uni.hideLoading()
      }
    },
    trackApi(promise) {
      if (!promise || typeof promise.then !== 'function') {
        return Promise.resolve(promise)
      }
      this._beginApiLoading()
      return promise.finally(() => {
        this._endApiLoading()
      })
    },
    eventDataAddWithLoading(data) {
      return this.trackApi(eventDataAdd(data))
    },
    lanch(url) {
      this._beginApiLoading()
      setTimeout(() => {
        this._endApiLoading()
        uni.navigateTo({
          url,
        })
      }, 500)
    },
