```79:103:zhi2-web-admin/src/views/benefit/dataSandbox/pieLegendHover.js
  const resetPieHover = (params) => {
    const action = { type: 'downplay' }
    if (params?.seriesType === 'pie' && params.name != null) {
      action.seriesIndex = params.seriesIndex ?? 0
