```66:104:d:\repository\产品2.0\zhi2-web-admin\src\store\modules\permission.js
const isBTerminalRedirectComponent = (component) => {
  return component === 'sso/bTerminalRedirect' || component === 'sso/bTerminalRedirect/index'
}

const isExternalLinkRouteComponent = (component) => {
  return isInnerLinkComponent(component) || isBTerminalRedirectComponent(component)
}

/** 内链 iframe / B 端 SSO 跳转：外链地址写入 meta.link，path 使用内部路由 */
const normalizeExternalLinkRoute = (route) => {
  // ...
}
```

同时增强了 `bTerminalRedirect/index.vue` 中 `resolveRedirectUrl` 对 `meta.link` 的解析。

## 菜单配置方式

| 字段 | 值 |
|------|-----|
| 组件路径 | `sso/bTerminalRedirect/index` |
| 路由地址 | `https://your-b-terminal-domain.com/callback` |
| 业务编码 | 对应的 `clientId`（busCode） |

