function createProxyConfig(target, proxyContext) {
  const shouldStripApiPrefix = proxyContext && String(proxyContext).startsWith("/api");

  return {
    target,
    changeOrigin: true,
    ...(shouldStripApiPrefix
      ? {
          rewrite: (path) => path.replace(/^\/api/, ""),
        }
      : {}),
    bypass(req, res, options) {
      const rewrittenUrl = options.rewrite ? options.rewrite(req.url) : req.url;
      res.setHeader("frontend-proxy", `${options.target}${rewrittenUrl}`);
    },
  };
}
```

